    One small optimization: hoist `px[i], py[i], pz[i]` to avoid repeated indexing in the inner loop. (Already planned).

    Wait, one more thing. The Apple M4 is ARM. Clang on macOS is quite good at auto-vectorizing this specific pattern (N-body) even without `#pragma omp simd`. But adding it explicitly doesn't hurt and can help if the compiler is cautious.

    Let's consider if `schedule(dynamic)` would be better than `guided`. `dynamic` has slightly more overhead because it asks for a new chunk every `chunk_size`. `guided` is usually smoother. Given the uniform cost per body, `guided` is a safe and efficient bet.

```c
/* k07_nbody: all-pairs gravitational acceleration, one step.
 * UNIFORM cost per body (each body visits all n others), compute-bound. */
#include <math.h>
#include <omp.h>
#include "common.h"

/* === KERNEL BEGIN === */
static void kernel(int n, const double *px, const double *py, const double *pz,
                   const double *m, double *ax, double *ay, double *az) {
    /* 
     * The outer loop is perfectly parallel.
     * Since we have a mix of P-cores and E-cores, 'schedule(guided)' is used 
     * to balance the load, allowing faster cores to process more work.
     */
    #pragma omp parallel for schedule(guided)
    for (int i = 0; i < n; i++) {
        double pxi = px[i];
        double pyi = py[i];
        double pzi = pz[i];
        double sx = 0.0, sy = 0.0, sz = 0.0;

        /* 
         * The inner loop is the bottleneck. We use 'omp simd' to encourage 
         * the compiler to utilize the M4's NEON/SIMD units. 
         * The reductions on sx, sy, and sz are handled in vector registers.
         */
        #pragma omp simd reduction(+:sx, sy, sz)
        for (int j = 0; j < n; j++) {
            double dx = px[j] - pxi;
            double dy = py[j] - pyi;
            double dz = pz[j] - pzi;
            double r2 = dx * dx + dy * dy + dz * dz + 1e-9;   /* softening */
            double inv = m[j] / (r2 * sqrt(r2));
            sx += dx * inv; 
            sy += dy * inv; 
            sz += dz * inv;
        }
        ax[i] = sx; 
        ay[i] = sy; 
        az[i] = sz;
    }
}
/* === KERNEL END === */

int main(int argc, char **argv) {
    int n = (int)arg_long(argc, argv, 1, 12000);
    double *b = xmalloc(7L * n * sizeof *b);
    double *px = b, *py = b + n, *pz = b + 2L * n, *m = b + 3L * n;
    double *ax = b + 4L * n, *ay = b + 5L * n, *az = b + 6L * n;
    rng_seed(7);
    for (int i = 0; i < n; i++) { px[i] = rng_unit(); py[i] = rng_unit(); pz[i] = rng_unit(); m[i] = rng_unit(); }

    double t0 = now_sec();
    kernel(n, px, py, pz, m, ax, ay, az);
    double t1 = now_sec();

    double sum = 0.0;
    for (int i = 0; i < n; i++) sum += fabs(ax[i]) + fabs(ay[i]) + fabs(az[i]);
    report("nbody", t1 - t0, sum);
    free(b);
    return 0;
}

